import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第四册：流利英语 · Lesson 24 Beauty","description":"学习 否定或限制副词前置倒装，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 24 Beauty","description":"学习 否定或限制副词前置倒装，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 否定或限制副词前置倒装，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 23 Bird flight","link":"/life/english/new-concept/book-4/unit-03/lesson-023"},"next":{"text":"第四册：流利英语 · Lesson 25 Non-auditory effects of noise","link":"/life/english/new-concept/book-4/unit-04/lesson-025"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 23 Bird flight","link":"/life/english/new-concept/book-4/unit-03/lesson-023"},"next":{"text":"第四册：流利英语 · Lesson 25 Non-auditory effects of noise","link":"/life/english/new-concept/book-4/unit-04/lesson-025"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-03/lesson-024.md","filePath":"life/english/new-concept/book-4/unit-03/lesson-024.md"}'),i={name:"life/english/new-concept/book-4/unit-03/lesson-024.md"};function l(r,e,s,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第四册-流利英语-·-lesson-24-beauty" tabindex="-1">第四册：流利英语 · Lesson 24 Beauty <a class="header-anchor" href="#第四册-流利英语-·-lesson-24-beauty" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 24 Beauty&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕审美判断训练抽象议论阅读，分清个人喜好、群体惯例与普遍标准。讨论一个物品或作品时，用颜色、比例、材料等可观察特征解释感受，而不是把“美”当成无需说明的事实。重点掌握否定前置倒装，用恰当强调表达观点的限定范围。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>beauty</td><td>/ˈbjuːti/</td><td>n.</td><td>美</td><td>a sense of beauty</td></tr><tr><td>proportion</td><td>/prəˈpɔːʃən/</td><td>n.</td><td>比例</td><td>balanced proportions</td></tr><tr><td>judgement</td><td>/ˈdʒʌdʒmənt/</td><td>n.</td><td>判断</td><td>an aesthetic judgement</td></tr><tr><td>texture</td><td>/ˈtekstʃə/</td><td>n.</td><td>质感</td><td>a rough texture</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>appeal to — 吸引某人</li><li>in the eye of — 从某人的眼光来看</li></ul><h2 id="语法讲解-否定或限制副词前置倒装" tabindex="-1">语法讲解：否定或限制副词前置倒装 <a class="header-anchor" href="#语法讲解-否定或限制副词前置倒装" aria-label="Permalink to &quot;语法讲解：否定或限制副词前置倒装&quot;">​</a></h2><p>Never、rarely、seldom、not until 等放在句首强调时，主句通常采用助动词在主语之前的部分倒装：Rarely do we agree on every detail。原句没有助动词时根据时态添加 do/does/did，实义动词恢复原形。Not until 引导时间短语或从句时，倒装发生在后面的主句，而不是 until 从句。倒装增加修辞强调，日常说明无需句句使用。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Rarely do two viewers notice exactly the same details in a painting.</p></blockquote><p>两位观者很少会注意到一幅画中完全相同的细节。</p><p>Rarely 前置触发 do two viewers 的部分倒装；notice 保持原形；不是把整句完全颠倒。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Rarely two viewers notice… 缺倒装；Rarely do two viewers notices… 又错误地给实义动词加 s。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>重读 Rarely 后顺畅读 do two viewers；录音核对 do 是否清晰、notice 是否保持原形发音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Rarely do I notice the shape of an ordinary cup. This one has a narrow base and a softly curved handle. I find the proportions pleasing, although another viewer may prefer a simpler form.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>选择一件普通物品写三句审美评论，包含一个具体特征和一个观点限制。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>倒装引入反思，具体特征支撑个人评价，让步句保留不同审美。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：Rarely ___ she choose bright colours.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> does</p><p><strong>解析：</strong> 主语 she，现时一般时倒装用 does。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>还原示例为普通语序。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Two viewers rarely notice exactly the same details in a painting.</p><p><strong>解析：</strong> rarely 回到实义动词前，取消 do。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>改写：I understood the design only after I touched the material. 以 Not until 开头。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Not until I touched the material did I understand the design.</p><p><strong>解析：</strong> until 从句不倒装，主句使用 did I understand。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：否定或限制副词前置倒装。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-023">上一课</a> · <a href="/life/english/new-concept/book-4/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-04/lesson-025">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(i,[["render",l]]);export{p as __pageData,b as default};
